---@field TxtTime                       	UnityEngine.RectTransform               
local ActivityCakeShopMainLineNode = Class('ActivityCakeShopMainLineNode')
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')

function ActivityCakeShopMainLineNode:__init()

end

function ActivityCakeShopMainLineNode:__delete()

end

function ActivityCakeShopMainLineNode:Awake()
    SetButtonAction(self.controller.gameObject,Bind(self,self.OnBtnNodeClick))
end

function ActivityCakeShopMainLineNode:OnBtnNodeClick()
    if not self.isPass and not self.isUnLock then
        local time = checkNumber(self.data.unlockCountdown) - os.time()
        if time > 0 then
            GameUtils.Toast(localize("_num_开启",{_num_ = CfUtils.GetTimeHMS11(time)}))
        else
            GameUtils.Toast(localize("请先通关前置关卡"))
        end
        return
    end
    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityCakeShopMainLineDetailsDialog,parameters = { questId = self.data.questId,index = self.index }},{{id = Constants.UITypeIds.ActivityCakeShopMainLineDialog}})
end

function ActivityCakeShopMainLineNode:RefreshChapterNodeShow(data,index)
    self.data = data
    self.index = index
    self:SetLockState()
    local vo = ActivityCakeUtils.GetChapterPlaceVo(self.data.questId)
    if not isNull(vo) then
       CfUtils.FillText(self.TxtName,vo.name)
    end
end

function ActivityCakeShopMainLineNode:SetLockState()
    local isPass = ActivityCakeUtils.GetActivityCakeMgr():IsPassChapterNode(self.data.questId)
    self.isPass = isPass
    if isPass then
        KTool.SetActive(self.Lock.gameObject,false)
        KTool.SetActive(self.Normal.gameObject,true)
        KTool.SetActive(self.Finish.gameObject,true)
    else
        local isUnLock = (checkNumber(self.data.unlockCountdown) - os.time()) <= 0 and ActivityCakeUtils.GetActivityCakeMgr():IsUnLockFirstChapter(self.data.questId)
        self.isUnLock = isUnLock
        if isUnLock then
            KTool.SetActive(self.Lock.gameObject,false)
            KTool.SetActive(self.Normal.gameObject,true)
            KTool.SetActive(self.Finish.gameObject,false)
        else
            KTool.SetActive(self.Lock.gameObject,true)
            KTool.SetActive(self.Normal.gameObject,false)
            KTool.SetActive(self.Finish.gameObject,false)
            self:SetLockParams()
        end
    end
end

function ActivityCakeShopMainLineNode:SetLockParams()
    local time = checkNumber(self.data.unlockCountdown) - os.time()
    if time > 0 then
        CfUtils.FillText(self.TxtTime,localize("_num_开启",{_num_ = CfUtils.GetTimeHMS11(time)}))
    else
        CfUtils.FillText(self.TxtTime,localize("请先通关前置关卡"))
    end
end

function ActivityCakeShopMainLineNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ActivityCakeShopMainLineNode